import{_ as r,l as s,o as e,c as n,v as t,p as l,x as o,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"会话管理","description":"","frontmatter":{"title":"会话管理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/session-management.md","filePath":"cs/session-management.md","lastUpdated":1789023840000}'),h={name:"cs/session-management.md"};function m(u,a,_,A,E,S){const i=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="会话管理" tabindex="-1">会话管理 <a class="header-anchor" href="#会话管理" aria-label="Permalink to &quot;会话管理&quot;">​</a></h1><div class="epigraph"><p>会话把「已认证」记在服务器或绑定在 cookie 上。标识要不可猜、要随权限变化而更新、要能作废。Secure、HttpOnly、SameSite 是浏览器合同，不是装饰性旗标。</p><footer>—— 据 RFC 6265；OWASP 会话管理；对照 Felten 等对 cookie 的早期讨论</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/jwt-pitfalls">JWT</a>给了一种无状态形状。缺口是<strong>有状态会话仍是默认</strong>：会话 ID、固定、CSRF、超时。不重写 CSRF 课的全部，只把会话生命周期钉进身份单元。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>登录后若不换会话 ID，固定攻击把预种 ID 升级成认证会话——只陈述性质。cookie 缺 Secure 则明文泄漏；缺 HttpOnly 则 XSS 可偷。缺口是生命周期与旗标，不是再讲表单。</p><h3 id="登出必须作废服务端" tabindex="-1">登出必须作废服务端 <a class="header-anchor" href="#登出必须作废服务端" aria-label="Permalink to &quot;登出必须作废服务端&quot;">​</a></h3><p>删浏览器 cookie 而服务端仍认 ID，等于没登出。</p><p><span class="marginnote">RFC 6265。SameSite 缓解部分 CSRF，不是全部。本课不给窃取 cookie 的步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：认证成功→换 ID→设旗标→绝对与空闲超时→吊销。对照 JWT 访问令牌+刷新。多设备会话要能列与踢。</p>',12)),(e(),l(p,null,{default:o(()=>[c(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOGIN%5B%22%E8%AE%A4%E8%AF%81%E6%88%90%E5%8A%9F%22%5D%20--%3E%20ROT%5B%22%E8%BD%AE%E6%8D%A2%E4%BC%9A%E8%AF%9D%20ID%22%5D%0A%20%20ROT%20--%3E%20FLAG%5B%22Secure%20HttpOnly%20SameSite%22%5D%0A%20%20FLAG%20--%3E%20TTL%5B%22%E8%B6%85%E6%97%B6%E4%B8%8E%E5%90%8A%E9%94%80%22%5D%0A%20%20TTL%20--%3E%20OUT%5B%22%E7%99%BB%E5%87%BA%E4%BD%9C%E5%BA%9F%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>身份是时间上的状态机。OAuth 下一课把这台机器拆成授权码、重定向与客户端类型——会话仍要，只是多了第三方。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把全部 cookie 前缀写完。OAuth 攻击面下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>JWT 无状态；会话 ID 有状态，要轮换与作废。</li><li>旗标与超时是合同；登出在服务端。</li><li>固定会话是认证前 ID 被绑上用户。</li><li>下一课 OAuth 攻击面。</li><li>出处：RFC 6265；OWASP Session Management；对照 RFC 6819。</li></ul>',8))])}const D=r(h,[["render",m]]);export{f as __pageData,D as default};
